package dev.folio;import org.springframework.data.jpa.repository.JpaRepository;import java.util.*;public interface LoanRepository extends JpaRepository<Loan,Long>{List<Loan> findByStudentIdAndReturnedOnIsNull(String studentId);List<Loan> findByStudentIdAndReturnedOnIsNotNullOrderByReturnedOnDesc(String studentId);Optional<Loan> findByIdAndStudentIdAndReturnedOnIsNull(Long id,String studentId);}